import type { NistCatalogFamily } from "../types.js";

// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_IR: NistCatalogFamily = {"code":"IR","name":"Incident Response","controls":[{"id":"IR-1","oscal_id":"ir-1","family":"IR","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> incident response policy that:\n    <organization-defined parameter> incident response policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the incident response policy and the associated incident response controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the incident response policy and procedures; and\nc. Review and update the current incident response:\n  Review and update the current incident response:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Incident response policy and procedures address the controls in the IR family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of incident response policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to incident response policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"ir-1_prm_1","label":"organization-defined personnel or roles"},{"id":"ir-01_odp.01","label":"personnel or roles"},{"id":"ir-01_odp.02","label":"personnel or roles"},{"id":"ir-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"ir-01_odp.04","label":"official"},{"id":"ir-01_odp.05","label":"frequency"},{"id":"ir-01_odp.06","label":"events"},{"id":"ir-01_odp.07","label":"frequency"},{"id":"ir-01_odp.08","label":"events"}],"objectives":[{"id":"ir-1_obj.a-1","label":"IR-01a.[01]","text":"an incident response policy is developed and documented;"},{"id":"ir-1_obj.a-2","label":"IR-01a.[02]","text":"the incident response policy is disseminated to {{ insert: param, ir-01_odp.01 }};"},{"id":"ir-1_obj.a-3","label":"IR-01a.[03]","text":"incident response procedures to facilitate the implementation of the incident response policy and associated incident response controls are developed and documented;"},{"id":"ir-1_obj.a-4","label":"IR-01a.[04]","text":"the incident response procedures are disseminated to {{ insert: param, ir-01_odp.02 }};"},{"id":"ir-1_obj.a.1.a-1","label":"IR-01a.01(a)[01]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses purpose;"},{"id":"ir-1_obj.a.1.a-2","label":"IR-01a.01(a)[02]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses scope;"},{"id":"ir-1_obj.a.1.a-3","label":"IR-01a.01(a)[03]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses roles;"},{"id":"ir-1_obj.a.1.a-4","label":"IR-01a.01(a)[04]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses responsibilities;"},{"id":"ir-1_obj.a.1.a-5","label":"IR-01a.01(a)[05]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses management commitment;"},{"id":"ir-1_obj.a.1.a-6","label":"IR-01a.01(a)[06]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses coordination among organizational entities;"},{"id":"ir-1_obj.a.1.a-7","label":"IR-01a.01(a)[07]","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy addresses compliance;"},{"id":"ir-1_obj.a.1.b","label":"IR-01a.01(b)","text":"the {{ insert: param, ir-01_odp.03 }} incident response policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ir-1_obj.b","label":"IR-01b.","text":"the {{ insert: param, ir-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the incident response policy and procedures;"},{"id":"ir-1_obj.c.1-1","label":"IR-01c.01[01]","text":"the current incident response policy is reviewed and updated {{ insert: param, ir-01_odp.05 }};"},{"id":"ir-1_obj.c.1-2","label":"IR-01c.01[02]","text":"the current incident response policy is reviewed and updated following {{ insert: param, ir-01_odp.06 }};"},{"id":"ir-1_obj.c.2-1","label":"IR-01c.02[01]","text":"the current incident response procedures are reviewed and updated {{ insert: param, ir-01_odp.07 }};"},{"id":"ir-1_obj.c.2-2","label":"IR-01c.02[02]","text":"the current incident response procedures are reviewed and updated following {{ insert: param, ir-01_odp.08 }}."}],"methods":[{"method":"examine","label":"IR-01-Examine"},{"method":"interview","label":"IR-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-50"},{"title":"SP 800-61"},{"title":"SP 800-83"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"IR-2","oscal_id":"ir-2","family":"IR","title":"Incident Response Training","statement":"a. Provide incident response training to system users consistent with assigned roles and responsibilities:\n  Provide incident response training to system users consistent with assigned roles and responsibilities:\n  1. Within <time period> of assuming an incident response role or responsibility or acquiring system access;\n  2. When required by system changes; and\n  3. <frequency> thereafter; and\nb. Review and update incident response training content <frequency> and following <events>.","supplemental_guidance":"Incident response training is associated with the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail are included in such training. For example, users may only need to know who to call or how to recognize an incident; system administrators may require additional training on how to handle incidents; and incident responders may receive more specific training on forensics, data collection techniques, reporting, system recovery, and system restoration. Incident response training includes user training in identifying and reporting suspicious activities from external and internal sources. Incident response training for users may be provided as part of [AT-2](#at-2) or [AT-3](#at-3) . Events that may precipitate an update to incident response training content include, but are not limited to, incident response plan testing or response to an actual incident (lessons learned), assessment or audit findings, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.","implementation_level":"organization","parameters":[{"id":"ir-02_odp.01","label":"time period"},{"id":"ir-02_odp.02","label":"frequency"},{"id":"ir-02_odp.03","label":"frequency"},{"id":"ir-02_odp.04","label":"events"}],"objectives":[{"id":"ir-2_obj.a.1","label":"IR-02a.01","text":"incident response training is provided to system users consistent with assigned roles and responsibilities within {{ insert: param, ir-02_odp.01 }} of assuming an incident response role or responsibility or acquiring system access;"},{"id":"ir-2_obj.a.2","label":"IR-02a.02","text":"incident response training is provided to system users consistent with assigned roles and responsibilities when required by system changes;"},{"id":"ir-2_obj.a.3","label":"IR-02a.03","text":"incident response training is provided to system users consistent with assigned roles and responsibilities {{ insert: param, ir-02_odp.02 }} thereafter;"},{"id":"ir-2_obj.b-1","label":"IR-02b.[01]","text":"incident response training content is reviewed and updated {{ insert: param, ir-02_odp.03 }};"},{"id":"ir-2_obj.b-2","label":"IR-02b.[02]","text":"incident response training content is reviewed and updated following {{ insert: param, ir-02_odp.04 }}."}],"methods":[{"method":"examine","label":"IR-02-Examine"},{"method":"interview","label":"IR-02-Interview"}],"references":[{"title":"OMB M-17-12"},{"title":"SP 800-50"}],"related_controls":["AT-2","AT-3","AT-4","CP-3","IR-3","IR-4","IR-8","IR-9"],"enhancements":[{"id":"IR-2(1)","oscal_id":"ir-2.1","family":"IR","title":"Simulated Events","statement":"Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations.","supplemental_guidance":"Organizations establish requirements for responding to incidents in incident response plans. Incorporating simulated events into incident response training helps to ensure that personnel understand their individual responsibilities and what specific actions to take in crisis situations.","implementation_level":"organization","methods":[{"method":"examine","label":"IR-02(01)-Examine"},{"method":"interview","label":"IR-02(01)-Interview"},{"method":"test","label":"IR-02(01)-Test"}],"is_enhancement":true,"parent_id":"IR-2"},{"id":"IR-2(2)","oscal_id":"ir-2.2","family":"IR","title":"Automated Training Environments","statement":"Provide an incident response training environment using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms can provide a more thorough and realistic incident response training environment. This can be accomplished, for example, by providing more complete coverage of incident response issues, selecting more realistic training scenarios and environments, and stressing the response capability.","implementation_level":"organization","parameters":[{"id":"ir-02.02_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"IR-02(02)-Examine"},{"method":"interview","label":"IR-02(02)-Interview"},{"method":"test","label":"IR-02(02)-Test"}],"is_enhancement":true,"parent_id":"IR-2"},{"id":"IR-2(3)","oscal_id":"ir-2.3","family":"IR","title":"Breach","statement":"Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.","supplemental_guidance":"For federal agencies, an incident that involves personally identifiable information is considered a breach. A breach results in the loss of control, compromise, unauthorized disclosure, unauthorized acquisition, or a similar occurrence where a person other than an authorized user accesses or potentially accesses personally identifiable information or an authorized user accesses or potentially accesses such information for other than authorized purposes. The incident response training emphasizes the obligation of individuals to report both confirmed and suspected breaches involving information in any medium or form, including paper, oral, and electronic. Incident response training includes tabletop exercises that simulate a breach. See [IR-2(1)](#ir-2.1).","implementation_level":"organization","objectives":[{"id":"ir-2.3_obj-1","label":"IR-02(03)[01]","text":"incident response training on how to identify and respond to a breach is provided;"},{"id":"ir-2.3_obj-2","label":"IR-02(03)[02]","text":"incident response training on the organization’s process for reporting a breach is provided."}],"methods":[{"method":"examine","label":"IR-02(03)-Examine"},{"method":"interview","label":"IR-02(03)-Interview"}],"is_enhancement":true,"parent_id":"IR-2"}]},{"id":"IR-3","oscal_id":"ir-3","family":"IR","title":"Incident Response Testing","statement":"Test the effectiveness of the incident response capability for the system <frequency> using the following tests: <tests>.","supplemental_guidance":"Organizations test incident response capabilities to determine their effectiveness and identify potential weaknesses or deficiencies. Incident response testing includes the use of checklists, walk-through or tabletop exercises, and simulations (parallel or full interrupt). Incident response testing can include a determination of the effects on organizational operations and assets and individuals due to incident response. The use of qualitative and quantitative data aids in determining the effectiveness of incident response processes.","implementation_level":"organization","parameters":[{"id":"ir-03_odp.01","label":"frequency"},{"id":"ir-03_odp.02","label":"tests"}],"methods":[{"method":"examine","label":"IR-03-Examine"},{"method":"interview","label":"IR-03-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-84"},{"title":"SP 800-115"}],"related_controls":["CP-3","CP-4","IR-2","IR-4","IR-8","PM-14"],"enhancements":[{"id":"IR-3(1)","oscal_id":"ir-3.1","family":"IR","title":"Automated Testing","statement":"Test the incident response capability using <automated mechanisms>.","supplemental_guidance":"Organizations use automated mechanisms to more thoroughly and effectively test incident response capabilities. This can be accomplished by providing more complete coverage of incident response issues, selecting realistic test scenarios and environments, and stressing the response capability.","implementation_level":"organization","parameters":[{"id":"ir-03.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"IR-03(01)-Examine"},{"method":"interview","label":"IR-03(01)-Interview"},{"method":"test","label":"IR-03(01)-Test"}],"is_enhancement":true,"parent_id":"IR-3"},{"id":"IR-3(2)","oscal_id":"ir-3.2","family":"IR","title":"Coordination with Related Plans","statement":"Coordinate incident response testing with organizational elements responsible for related plans.","supplemental_guidance":"Organizational plans related to incident response testing include business continuity plans, disaster recovery plans, continuity of operations plans, contingency plans, crisis communications plans, critical infrastructure plans, and occupant emergency plans.","implementation_level":"organization","methods":[{"method":"examine","label":"IR-03(02)-Examine"},{"method":"interview","label":"IR-03(02)-Interview"}],"is_enhancement":true,"parent_id":"IR-3"},{"id":"IR-3(3)","oscal_id":"ir-3.3","family":"IR","title":"Continuous Improvement","statement":"Use qualitative and quantitative data from testing to:\n(a) Determine the effectiveness of incident response processes;\n(b) Continuously improve incident response processes; and\n(c) Provide incident response measures and metrics that are accurate, consistent, and in a reproducible format.","supplemental_guidance":"To help incident response activities function as intended, organizations may use metrics and evaluation criteria to assess incident response programs as part of an effort to continually improve response performance. These efforts facilitate improvement in incident response efficacy and lessen the impact of incidents.","implementation_level":"organization","objectives":[{"id":"ir-3.3_obj.a-1","label":"IR-03(03)(a)[01]","text":"qualitative data from testing are used to determine the effectiveness of incident response processes;"},{"id":"ir-3.3_obj.a-2","label":"IR-03(03)(a)[02]","text":"quantitative data from testing are used to determine the effectiveness of incident response processes;"},{"id":"ir-3.3_obj.b-1","label":"IR-03(03)(b)[01]","text":"qualitative data from testing are used to continuously improve incident response processes;"},{"id":"ir-3.3_obj.b-2","label":"IR-03(03)(b)[02]","text":"quantitative data from testing are used to continuously improve incident response processes;"},{"id":"ir-3.3_obj.c-1","label":"IR-03(03)(c)[01]","text":"qualitative data from testing are used to provide incident response measures and metrics that are accurate;"},{"id":"ir-3.3_obj.c-2","label":"IR-03(03)(c)[02]","text":"quantitative data from testing are used to provide incident response measures and metrics that are accurate;"},{"id":"ir-3.3_obj.c-3","label":"IR-03(03)(c)[03]","text":"qualitative data from testing are used to provide incident response measures and metrics that are consistent;"},{"id":"ir-3.3_obj.c-4","label":"IR-03(03)(c)[04]","text":"quantitative data from testing are used to provide incident response measures and metrics that are consistent;"},{"id":"ir-3.3_obj.c-5","label":"IR-03(03)(c)[05]","text":"qualitative data from testing are used to provide incident response measures and metrics in a reproducible format;"},{"id":"ir-3.3_obj.c-6","label":"IR-03(03)(c)[06]","text":"quantitative data from testing are used to provide incident response measures and metrics in a reproducible format."}],"methods":[{"method":"examine","label":"IR-03(03)-Examine"},{"method":"interview","label":"IR-03(03)-Interview"}],"is_enhancement":true,"parent_id":"IR-3"}]},{"id":"IR-4","oscal_id":"ir-4","family":"IR","title":"Incident Handling","statement":"a. Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery;\nb. Coordinate incident handling activities with contingency planning activities;\nc. Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; and\nd. Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization.","supplemental_guidance":"Organizations recognize that incident response capabilities are dependent on the capabilities of organizational systems and the mission and business processes being supported by those systems. Organizations consider incident response as part of the definition, design, and development of mission and business processes and systems. Incident-related information can be obtained from a variety of sources, including audit monitoring, physical access monitoring, and network monitoring; user or administrator reports; and reported supply chain events. An effective incident handling capability includes coordination among many organizational entities (e.g., mission or business owners, system owners, authorizing officials, human resources offices, physical security offices, personnel security offices, legal departments, risk executive [function], operations personnel, procurement offices). Suspected security incidents include the receipt of suspicious email communications that can contain malicious code. Suspected supply chain incidents include the insertion of counterfeit hardware or malicious code into organizational systems or system components. For federal agencies, an incident that involves personally identifiable information is considered a breach. A breach results in unauthorized disclosure, the loss of control, unauthorized acquisition, compromise, or a similar occurrence where a person other than an authorized user accesses or potentially accesses personally identifiable information or an authorized user accesses or potentially accesses such information for other than authorized purposes.","implementation_level":"organization","objectives":[{"id":"ir-4_obj.a-1","label":"IR-04a.[01]","text":"an incident handling capability for incidents is implemented that is consistent with the incident response plan;"},{"id":"ir-4_obj.a-2","label":"IR-04a.[02]","text":"the incident handling capability for incidents includes preparation;"},{"id":"ir-4_obj.a-3","label":"IR-04a.[03]","text":"the incident handling capability for incidents includes detection and analysis;"},{"id":"ir-4_obj.a-4","label":"IR-04a.[04]","text":"the incident handling capability for incidents includes containment;"},{"id":"ir-4_obj.a-5","label":"IR-04a.[05]","text":"the incident handling capability for incidents includes eradication;"},{"id":"ir-4_obj.a-6","label":"IR-04a.[06]","text":"the incident handling capability for incidents includes recovery;"},{"id":"ir-4_obj.b","label":"IR-04b.","text":"incident handling activities are coordinated with contingency planning activities;"},{"id":"ir-4_obj.c-1","label":"IR-04c.[01]","text":"lessons learned from ongoing incident handling activities are incorporated into incident response procedures, training, and testing;"},{"id":"ir-4_obj.c-2","label":"IR-04c.[02]","text":"the changes resulting from the incorporated lessons learned are implemented accordingly;"},{"id":"ir-4_obj.d-1","label":"IR-04d.[01]","text":"the rigor of incident handling activities is comparable and predictable across the organization;"},{"id":"ir-4_obj.d-2","label":"IR-04d.[02]","text":"the intensity of incident handling activities is comparable and predictable across the organization;"},{"id":"ir-4_obj.d-3","label":"IR-04d.[03]","text":"the scope of incident handling activities is comparable and predictable across the organization;"},{"id":"ir-4_obj.d-4","label":"IR-04d.[04]","text":"the results of incident handling activities are comparable and predictable across the organization."}],"methods":[{"method":"examine","label":"IR-04-Examine"},{"method":"interview","label":"IR-04-Interview"},{"method":"test","label":"IR-04-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"OMB M-17-12"},{"title":"SP 800-61"},{"title":"SP 800-86"},{"title":"SP 800-101"},{"title":"SP 800-150"},{"title":"SP 800-160-2"},{"title":"SP 800-184"},{"title":"IR 7559"}],"related_controls":["AC-19","AU-6","AU-7","CM-6","CP-2","CP-3","CP-4","IR-2","IR-3","IR-5","IR-6","IR-8","PE-6","PL-2","PM-12","SA-8","SC-5","SC-7","SI-3","SI-4","SI-7"],"enhancements":[{"id":"IR-4(1)","oscal_id":"ir-4.1","family":"IR","title":"Automated Incident Handling Processes","statement":"Support the incident handling process using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms that support incident handling processes include online incident management systems and tools that support the collection of live response data, full network packet capture, and forensic analysis.","implementation_level":"organization","parameters":[{"id":"ir-04.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"IR-04(01)-Examine"},{"method":"interview","label":"IR-04(01)-Interview"},{"method":"test","label":"IR-04(01)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(2)","oscal_id":"ir-4.2","family":"IR","title":"Dynamic Reconfiguration","statement":"Include the following types of dynamic reconfiguration for <system components> as part of the incident response capability: <types of dynamic reconfiguration>.","supplemental_guidance":"Dynamic reconfiguration includes changes to router rules, access control lists, intrusion detection or prevention system parameters, and filter rules for guards or firewalls. Organizations may perform dynamic reconfiguration of systems to stop attacks, misdirect attackers, and isolate components of systems, thus limiting the extent of the damage from breaches or compromises. Organizations include specific time frames for achieving the reconfiguration of systems in the definition of the reconfiguration capability, considering the potential need for rapid response to effectively address cyber threats.","implementation_level":"organization","parameters":[{"id":"ir-04.02_odp.01","label":"types of dynamic reconfiguration"},{"id":"ir-04.02_odp.02","label":"system components"}],"methods":[{"method":"examine","label":"IR-04(02)-Examine"},{"method":"interview","label":"IR-04(02)-Interview"},{"method":"test","label":"IR-04(02)-Test"}],"related_controls":["AC-2","AC-4","CM-2"],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(3)","oscal_id":"ir-4.3","family":"IR","title":"Continuity of Operations","statement":"Identify <classes of incidents> and take the following actions in response to those incidents to ensure continuation of organizational mission and business functions: <actions>.","supplemental_guidance":"Classes of incidents include malfunctions due to design or implementation errors and omissions, targeted malicious attacks, and untargeted malicious attacks. Incident response actions include orderly system degradation, system shutdown, fall back to manual mode or activation of alternative technology whereby the system operates differently, employing deceptive measures, alternate information flows, or operating in a mode that is reserved for when systems are under attack. Organizations consider whether continuity of operations requirements during an incident conflict with the capability to automatically disable the system as specified as part of [IR-4(5)](#ir-4.5).","implementation_level":"organization","parameters":[{"id":"ir-04.03_odp.01","label":"classes of incidents"},{"id":"ir-04.03_odp.02","label":"actions"}],"objectives":[{"id":"ir-4.3_obj-1","label":"IR-04(03)[01]","text":"{{ insert: param, ir-04.03_odp.01 }} are identified;"},{"id":"ir-4.3_obj-2","label":"IR-04(03)[02]","text":"{{ insert: param, ir-04.03_odp.02 }} are taken in response to those incidents (defined in IR-04(03)_ODP[01]) to ensure the continuation of organizational mission and business functions."}],"methods":[{"method":"examine","label":"IR-04(03)-Examine"},{"method":"interview","label":"IR-04(03)-Interview"},{"method":"test","label":"IR-04(03)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(4)","oscal_id":"ir-4.4","family":"IR","title":"Information Correlation","statement":"Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response.","supplemental_guidance":"Sometimes, a threat event, such as a hostile cyber-attack, can only be observed by bringing together information from different sources, including various reports and reporting procedures established by organizations.","implementation_level":"organization","methods":[{"method":"examine","label":"IR-04(04)-Examine"},{"method":"interview","label":"IR-04(04)-Interview"},{"method":"test","label":"IR-04(04)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(5)","oscal_id":"ir-4.5","family":"IR","title":"Automatic Disabling of System","statement":"Implement a configurable capability to automatically disable the system if <security violations> are detected.","supplemental_guidance":"Organizations consider whether the capability to automatically disable the system conflicts with continuity of operations requirements specified as part of [CP-2](#cp-2) or [IR-4(3)](#ir-4.3) . Security violations include cyber-attacks that have compromised the integrity of the system or exfiltrated organizational information and serious errors in software programs that could adversely impact organizational missions or functions or jeopardize the safety of individuals.","implementation_level":"organization","parameters":[{"id":"ir-04.05_odp","label":"security violations"}],"methods":[{"method":"examine","label":"IR-04(05)-Examine"},{"method":"interview","label":"IR-04(05)-Interview"},{"method":"test","label":"IR-04(05)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(6)","oscal_id":"ir-4.6","family":"IR","title":"Insider Threats","statement":"Implement an incident handling capability for incidents involving insider threats.","supplemental_guidance":"Explicit focus on handling incidents involving insider threats provides additional emphasis on this type of threat and the need for specific incident handling capabilities to provide appropriate and timely responses.","implementation_level":"organization","methods":[{"method":"examine","label":"IR-04(06)-Examine"},{"method":"interview","label":"IR-04(06)-Interview"},{"method":"test","label":"IR-04(06)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(7)","oscal_id":"ir-4.7","family":"IR","title":"Insider Threats — Intra-organization Coordination","statement":"Coordinate an incident handling capability for insider threats that includes the following organizational entities <entities>.","supplemental_guidance":"Incident handling for insider threat incidents (e.g., preparation, detection and analysis, containment, eradication, and recovery) requires coordination among many organizational entities, including mission or business owners, system owners, human resources offices, procurement offices, personnel offices, physical security offices, senior agency information security officer, operations personnel, risk executive (function), senior agency official for privacy, and legal counsel. In addition, organizations may require external support from federal, state, and local law enforcement agencies.","implementation_level":"organization","parameters":[{"id":"ir-04.07_odp","label":"entities"}],"objectives":[{"id":"ir-4.7_obj-1","label":"IR-04(07)[01]","text":"an incident handling capability is coordinated for insider threats;"},{"id":"ir-4.7_obj-2","label":"IR-04(07)[02]","text":"the coordinated incident handling capability includes {{ insert: param, ir-04.07_odp }}."}],"methods":[{"method":"examine","label":"IR-04(07)-Examine"},{"method":"interview","label":"IR-04(07)-Interview"},{"method":"test","label":"IR-04(07)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(8)","oscal_id":"ir-4.8","family":"IR","title":"Correlation with External Organizations","statement":"Coordinate with <external organizations> to correlate and share <incident information> to achieve a cross-organization perspective on incident awareness and more effective incident responses.","supplemental_guidance":"The coordination of incident information with external organizations—including mission or business partners, military or coalition partners, customers, and developers—can provide significant benefits. Cross-organizational coordination can serve as an important risk management capability. This capability allows organizations to leverage information from a variety of sources to effectively respond to incidents and breaches that could potentially affect the organization’s operations, assets, and individuals.","implementation_level":"organization","parameters":[{"id":"ir-04.08_odp.01","label":"external organizations"},{"id":"ir-04.08_odp.02","label":"incident information"}],"methods":[{"method":"examine","label":"IR-04(08)-Examine"},{"method":"interview","label":"IR-04(08)-Interview"},{"method":"test","label":"IR-04(08)-Test"}],"related_controls":["AU-16","PM-16"],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(9)","oscal_id":"ir-4.9","family":"IR","title":"Dynamic Response Capability","statement":"Employ <dynamic response capabilities> to respond to incidents.","supplemental_guidance":"The dynamic response capability addresses the timely deployment of new or replacement organizational capabilities in response to incidents. This includes capabilities implemented at the mission and business process level and at the system level.","implementation_level":"organization","parameters":[{"id":"ir-04.09_odp","label":"dynamic response capabilities"}],"methods":[{"method":"examine","label":"IR-04(09)-Examine"},{"method":"interview","label":"IR-04(09)-Interview"},{"method":"test","label":"IR-04(09)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(10)","oscal_id":"ir-4.10","family":"IR","title":"Supply Chain Coordination","statement":"Coordinate incident handling activities involving supply chain events with other organizations involved in the supply chain.","supplemental_guidance":"Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Supply chain incidents can occur anywhere through or to the supply chain and include compromises or breaches that involve primary or sub-tier providers, information technology products, system components, development processes or personnel, and distribution processes or warehousing facilities. Organizations consider including processes for protecting and sharing incident information in information exchange agreements and their obligations for reporting incidents to government oversight bodies (e.g., Federal Acquisition Security Council).","implementation_level":"organization","methods":[{"method":"examine","label":"IR-04(10)-Examine"},{"method":"interview","label":"IR-04(10)-Interview"}],"related_controls":["CA-3","MA-2","SA-9","SR-8"],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(11)","oscal_id":"ir-4.11","family":"IR","title":"Integrated Incident Response Team","statement":"Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in <time period>.","supplemental_guidance":"An integrated incident response team is a team of experts that assesses, documents, and responds to incidents so that organizational systems and networks can recover quickly and implement the necessary controls to avoid future incidents. Incident response team personnel include forensic and malicious code analysts, tool developers, systems security and privacy engineers, and real-time operations personnel. The incident handling capability includes performing rapid forensic preservation of evidence and analysis of and response to intrusions. For some organizations, the incident response team can be a cross-organizational entity.\n\nAn integrated incident response team facilitates information sharing and allows organizational personnel (e.g., developers, implementers, and operators) to leverage team knowledge of the threat and implement defensive measures that enable organizations to deter intrusions more effectively. Moreover, integrated teams promote the rapid detection of intrusions, the development of appropriate mitigations, and the deployment of effective defensive measures. For example, when an intrusion is detected, the integrated team can rapidly develop an appropriate response for operators to implement, correlate the new incident with information on past intrusions, and augment ongoing cyber intelligence development. Integrated incident response teams are better able to identify adversary tactics, techniques, and procedures that are linked to the operations tempo or specific mission and business functions and to define responsive actions in a way that does not disrupt those mission and business functions. Incident response teams can be distributed within organizations to make the capability resilient.","implementation_level":"organization","parameters":[{"id":"ir-04.11_odp","label":"time period"}],"objectives":[{"id":"ir-4.11_obj-1","label":"IR-04(11)[01]","text":"an integrated incident response team is established and maintained;"},{"id":"ir-4.11_obj-2","label":"IR-04(11)[02]","text":"the integrated incident response team can be deployed to any location identified by the organization in {{ insert: param, ir-04.11_odp }}."}],"methods":[{"method":"examine","label":"IR-04(11)-Examine"},{"method":"interview","label":"IR-04(11)-Interview"}],"related_controls":["AT-3"],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(12)","oscal_id":"ir-4.12","family":"IR","title":"Malicious Code and Forensic Analysis","statement":"Analyze malicious code and/or other residual artifacts remaining in the system after the incident.","supplemental_guidance":"When conducted carefully in an isolated environment, analysis of malicious code and other residual artifacts of a security incident or breach can give the organization insight into adversary tactics, techniques, and procedures. It can also indicate the identity or some defining characteristics of the adversary. In addition, malicious code analysis can help the organization develop responses to future incidents.","implementation_level":"organization","objectives":[{"id":"ir-4.12_obj-1","label":"IR-04(12)[01]","text":"malicious code remaining in the system is analyzed after the incident;"},{"id":"ir-4.12_obj-2","label":"IR-04(12)[02]","text":"other residual artifacts remaining in the system (if any) are analyzed after the incident."}],"methods":[{"method":"examine","label":"IR-04(12)-Examine"},{"method":"interview","label":"IR-04(12)-Interview"},{"method":"test","label":"IR-04(12)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(13)","oscal_id":"ir-4.13","family":"IR","title":"Behavior Analysis","statement":"Analyze anomalous or suspected adversarial behavior in or related to <environments or resources>.","supplemental_guidance":"If the organization maintains a deception environment, an analysis of behaviors in that environment, including resources targeted by the adversary and timing of the incident or event, can provide insight into adversarial tactics, techniques, and procedures. External to a deception environment, the analysis of anomalous adversarial behavior (e.g., changes in system performance or usage patterns) or suspected behavior (e.g., changes in searches for the location of specific resources) can give the organization such insight.","implementation_level":"organization","parameters":[{"id":"ir-04.13_odp","label":"environments or resources"}],"methods":[{"method":"examine","label":"IR-04(13)-Examine"},{"method":"interview","label":"IR-04(13)-Interview"},{"method":"test","label":"IR-04(13)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(14)","oscal_id":"ir-4.14","family":"IR","title":"Security Operations Center","statement":"Establish and maintain a security operations center.","supplemental_guidance":"A security operations center (SOC) is the focal point for security operations and computer network defense for an organization. The purpose of the SOC is to defend and monitor an organization’s systems and networks (i.e., cyber infrastructure) on an ongoing basis. The SOC is also responsible for detecting, analyzing, and responding to cybersecurity incidents in a timely manner. The organization staffs the SOC with skilled technical and operational personnel (e.g., security analysts, incident response personnel, systems security engineers) and implements a combination of technical, management, and operational controls (including monitoring, scanning, and forensics tools) to monitor, fuse, correlate, analyze, and respond to threat and security-relevant event data from multiple sources. These sources include perimeter defenses, network devices (e.g., routers, switches), and endpoint agent data feeds. The SOC provides a holistic situational awareness capability to help organizations determine the security posture of the system and organization. A SOC capability can be obtained in a variety of ways. Larger organizations may implement a dedicated SOC while smaller organizations may employ third-party organizations to provide such a capability.","implementation_level":"organization","objectives":[{"id":"ir-4.14_obj-1","label":"IR-04(14)[01]","text":"a security operations center is established;"},{"id":"ir-4.14_obj-2","label":"IR-04(14)[02]","text":"a security operations center is maintained."}],"methods":[{"method":"examine","label":"IR-04(14)-Examine"},{"method":"interview","label":"IR-04(14)-Interview"},{"method":"test","label":"IR-04(14)-Test"}],"is_enhancement":true,"parent_id":"IR-4"},{"id":"IR-4(15)","oscal_id":"ir-4.15","family":"IR","title":"Public Relations and Reputation Repair","statement":"(a) Manage public relations associated with an incident; and\n(b) Employ measures to repair the reputation of the organization.","supplemental_guidance":"It is important for an organization to have a strategy in place for addressing incidents that have been brought to the attention of the general public, have cast the organization in a negative light, or have affected the organization’s constituents (e.g., partners, customers). Such publicity can be extremely harmful to the organization and affect its ability to carry out its mission and business functions. Taking proactive steps to repair the organization’s reputation is an essential aspect of reestablishing the trust and confidence of its constituents.","implementation_level":"organization","objectives":[{"id":"ir-4.15_obj.a","label":"IR-04(15)(a)","text":"public relations associated with an incident are managed;"},{"id":"ir-4.15_obj.b","label":"IR-04(15)(b)","text":"measures are employed to repair the reputation of the organization."}],"methods":[{"method":"examine","label":"IR-04(15)-Examine"},{"method":"interview","label":"IR-04(15)-Interview"}],"is_enhancement":true,"parent_id":"IR-4"}]},{"id":"IR-5","oscal_id":"ir-5","family":"IR","title":"Incident Monitoring","statement":"Track and document incidents.","supplemental_guidance":"Documenting incidents includes maintaining records about each incident, the status of the incident, and other pertinent information necessary for forensics as well as evaluating incident details, trends, and handling. Incident information can be obtained from a variety of sources, including network monitoring, incident reports, incident response teams, user complaints, supply chain partners, audit monitoring, physical access monitoring, and user and administrator reports. [IR-4](#ir-4) provides information on the types of incidents that are appropriate for monitoring.","implementation_level":"organization","objectives":[{"id":"ir-5_obj-1","label":"IR-05[01]","text":"incidents are tracked;"},{"id":"ir-5_obj-2","label":"IR-05[02]","text":"incidents are documented."}],"methods":[{"method":"examine","label":"IR-05-Examine"},{"method":"interview","label":"IR-05-Interview"},{"method":"test","label":"IR-05-Test"}],"references":[{"title":"SP 800-61"}],"related_controls":["AU-6","AU-7","IR-4","IR-6","IR-8","PE-6","PM-5","SC-5","SC-7","SI-3","SI-4","SI-7"],"enhancements":[{"id":"IR-5(1)","oscal_id":"ir-5.1","family":"IR","title":"Automated Tracking, Data Collection, and Analysis","statement":"Track incidents and collect and analyze incident information using <organization-defined automated mechanisms>.","supplemental_guidance":"Automated mechanisms for tracking incidents and collecting and analyzing incident information include Computer Incident Response Centers or other electronic databases of incidents and network monitoring devices.","implementation_level":"organization","parameters":[{"id":"ir-5.1_prm_1","label":"organization-defined automated mechanisms"},{"id":"ir-05.01_odp.01","label":"automated mechanisms"},{"id":"ir-05.01_odp.02","label":"automated mechanisms"},{"id":"ir-05.01_odp.03","label":"automated mechanisms"}],"objectives":[{"id":"ir-5.1_obj-1","label":"IR-05(01)[01]","text":"incidents are tracked using {{ insert: param, ir-05.01_odp.01 }};"},{"id":"ir-5.1_obj-2","label":"IR-05(01)[02]","text":"incident information is collected using {{ insert: param, ir-05.01_odp.02 }};"},{"id":"ir-5.1_obj-3","label":"IR-05(01)[03]","text":"incident information is analyzed using {{ insert: param, ir-05.01_odp.03 }}."}],"methods":[{"method":"examine","label":"IR-05(01)-Examine"},{"method":"interview","label":"IR-05(01)-Interview"},{"method":"test","label":"IR-05(01)-Test"}],"is_enhancement":true,"parent_id":"IR-5"}]},{"id":"IR-6","oscal_id":"ir-6","family":"IR","title":"Incident Reporting","statement":"a. Require personnel to report suspected incidents to the organizational incident response capability within <time period> ; and\nb. Report incident information to <authorities>.","supplemental_guidance":"The types of incidents reported, the content and timeliness of the reports, and the designated reporting authorities reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Incident information can inform risk assessments, control effectiveness assessments, security requirements for acquisitions, and selection criteria for technology products.","implementation_level":"organization","parameters":[{"id":"ir-06_odp.01","label":"time period"},{"id":"ir-06_odp.02","label":"authorities"}],"objectives":[{"id":"ir-6_obj.a","label":"IR-06a.","text":"personnel is/are required to report suspected incidents to the organizational incident response capability within {{ insert: param, ir-06_odp.01 }};"},{"id":"ir-6_obj.b","label":"IR-06b.","text":"incident information is reported to {{ insert: param, ir-06_odp.02 }}."}],"methods":[{"method":"examine","label":"IR-06-Examine"},{"method":"interview","label":"IR-06-Interview"},{"method":"test","label":"IR-06-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"USCERT IR"},{"title":"SP 800-61"}],"related_controls":["CM-6","CP-2","IR-4","IR-5","IR-8","IR-9"],"enhancements":[{"id":"IR-6(1)","oscal_id":"ir-6.1","family":"IR","title":"Automated Reporting","statement":"Report incidents using <automated mechanisms>.","supplemental_guidance":"The recipients of incident reports are specified in [IR-6b](#ir-6_smt.b) . Automated reporting mechanisms include email, posting on websites (with automatic updates), and automated incident response tools and programs.","implementation_level":"organization","parameters":[{"id":"ir-06.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"IR-06(01)-Examine"},{"method":"interview","label":"IR-06(01)-Interview"},{"method":"test","label":"IR-06(01)-Test"}],"related_controls":["IR-7"],"is_enhancement":true,"parent_id":"IR-6"},{"id":"IR-6(2)","oscal_id":"ir-6.2","family":"IR","title":"Vulnerabilities Related to Incidents","statement":"Report system vulnerabilities associated with reported incidents to <personnel or roles>.","supplemental_guidance":"Reported incidents that uncover system vulnerabilities are analyzed by organizational personnel including system owners, mission and business owners, senior agency information security officers, senior agency officials for privacy, authorizing officials, and the risk executive (function). The analysis can serve to prioritize and initiate mitigation actions to address the discovered system vulnerability.","implementation_level":"organization","parameters":[{"id":"ir-06.02_odp","label":"personnel or roles"}],"methods":[{"method":"examine","label":"IR-06(02)-Examine"},{"method":"interview","label":"IR-06(02)-Interview"},{"method":"test","label":"IR-06(02)-Test"}],"is_enhancement":true,"parent_id":"IR-6"},{"id":"IR-6(3)","oscal_id":"ir-6.3","family":"IR","title":"Supply Chain Coordination","statement":"Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident.","supplemental_guidance":"Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Entities that provide supply chain governance include the Federal Acquisition Security Council (FASC). Supply chain incidents include compromises or breaches that involve information technology products, system components, development processes or personnel, distribution processes, or warehousing facilities. Organizations determine the appropriate information to share and consider the value gained from informing external organizations about supply chain incidents, including the ability to improve processes or to identify the root cause of an incident.","implementation_level":"organization","methods":[{"method":"examine","label":"IR-06(03)-Examine"},{"method":"interview","label":"IR-06(03)-Interview"},{"method":"test","label":"IR-06(03)-Test"}],"related_controls":["SR-8"],"is_enhancement":true,"parent_id":"IR-6"}]},{"id":"IR-7","oscal_id":"ir-7","family":"IR","title":"Incident Response Assistance","statement":"Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents.","supplemental_guidance":"Incident response support resources provided by organizations include help desks, assistance groups, automated ticketing systems to open and track incident response tickets, and access to forensics services or consumer redress services, when required.","implementation_level":"organization","objectives":[{"id":"ir-7_obj-1","label":"IR-07[01]","text":"an incident response support resource, integral to the organizational incident response capability, is provided;"},{"id":"ir-7_obj-2","label":"IR-07[02]","text":"the incident response support resource offers advice and assistance to users of the system for the response and reporting of incidents."}],"methods":[{"method":"examine","label":"IR-07-Examine"},{"method":"interview","label":"IR-07-Interview"},{"method":"test","label":"IR-07-Test"}],"references":[{"title":"OMB A-130"},{"title":"IR 7559"}],"related_controls":["AT-2","AT-3","IR-4","IR-6","IR-8","PM-22","PM-26","SA-9","SI-18"],"enhancements":[{"id":"IR-7(1)","oscal_id":"ir-7.1","family":"IR","title":"Automation Support for Availability of Information and Support","statement":"Increase the availability of incident response information and support using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms can provide a push or pull capability for users to obtain incident response assistance. For example, individuals may have access to a website to query the assistance capability, or the assistance capability can proactively send incident response information to users (general distribution or targeted) as part of increasing understanding of current response capabilities and support.","implementation_level":"organization","parameters":[{"id":"ir-07.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"IR-07(01)-Examine"},{"method":"interview","label":"IR-07(01)-Interview"},{"method":"test","label":"IR-07(01)-Test"}],"is_enhancement":true,"parent_id":"IR-7"},{"id":"IR-7(2)","oscal_id":"ir-7.2","family":"IR","title":"Coordination with External Providers","statement":"(a) Establish a direct, cooperative relationship between its incident response capability and external providers of system protection capability; and\n(b) Identify organizational incident response team members to the external providers.","supplemental_guidance":"External providers of a system protection capability include the Computer Network Defense program within the U.S. Department of Defense. External providers help to protect, monitor, analyze, detect, and respond to unauthorized activity within organizational information systems and networks. It may be beneficial to have agreements in place with external providers to clarify the roles and responsibilities of each party before an incident occurs.","implementation_level":"organization","objectives":[{"id":"ir-7.2_obj.a","label":"IR-07(02)(a)","text":"a direct, cooperative relationship is established between its incident response capability and external providers of the system protection capability;"},{"id":"ir-7.2_obj.b","label":"IR-07(02)(b)","text":"organizational incident response team members are identified to the external providers."}],"methods":[{"method":"examine","label":"IR-07(02)-Examine"},{"method":"interview","label":"IR-07(02)-Interview"}],"is_enhancement":true,"parent_id":"IR-7"}]},{"id":"IR-8","oscal_id":"ir-8","family":"IR","title":"Incident Response Plan","statement":"a. Develop an incident response plan that:\n  Develop an incident response plan that:\n  1. Provides the organization with a roadmap for implementing its incident response capability;\n  2. Describes the structure and organization of the incident response capability;\n  3. Provides a high-level approach for how the incident response capability fits into the overall organization;\n  4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions;\n  5. Defines reportable incidents;\n  6. Provides metrics for measuring the incident response capability within the organization;\n  7. Defines the resources and management support needed to effectively maintain and mature an incident response capability;\n  8. Addresses the sharing of incident information;\n  9. Is reviewed and approved by <personnel or roles> <frequency> ; and\n  10. Explicitly designates responsibility for incident response to <entities, personnel, or roles>.\nb. Distribute copies of the incident response plan to <incident response personnel>;\nc. Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing;\nd. Communicate incident response plan changes to <organization-defined incident response personnel (identified by name and/or by role) and organizational elements> ; and\ne. Protect the incident response plan from unauthorized disclosure and modification.","supplemental_guidance":"It is important that organizations develop and implement a coordinated approach to incident response. Organizational mission and business functions determine the structure of incident response capabilities. As part of the incident response capabilities, organizations consider the coordination and sharing of information with external organizations, including external service providers and other organizations involved in the supply chain. For incidents involving personally identifiable information (i.e., breaches), include a process to determine whether notice to oversight organizations or affected individuals is appropriate and provide that notice accordingly.","implementation_level":"organization","parameters":[{"id":"ir-8_prm_5","label":"organization-defined incident response personnel (identified by name and/or by role) and organizational elements"},{"id":"ir-08_odp.01","label":"personnel or roles"},{"id":"ir-08_odp.02","label":"frequency"},{"id":"ir-08_odp.03","label":"entities, personnel, or roles"},{"id":"ir-08_odp.04","label":"incident response personnel"},{"id":"ir-08_odp.05","label":"organizational elements"},{"id":"ir-08_odp.06","label":"incident response personnel"},{"id":"ir-08_odp.07","label":"organizational elements"}],"objectives":[{"id":"ir-8_obj.a.1","label":"IR-08a.01","text":"an incident response plan is developed that provides the organization with a roadmap for implementing its incident response capability;"},{"id":"ir-8_obj.a.2","label":"IR-08a.02","text":"an incident response plan is developed that describes the structure and organization of the incident response capability;"},{"id":"ir-8_obj.a.3","label":"IR-08a.03","text":"an incident response plan is developed that provides a high-level approach for how the incident response capability fits into the overall organization;"},{"id":"ir-8_obj.a.4","label":"IR-08a.04","text":"an incident response plan is developed that meets the unique requirements of the organization with regard to mission, size, structure, and functions;"},{"id":"ir-8_obj.a.5","label":"IR-08a.05","text":"an incident response plan is developed that defines reportable incidents;"},{"id":"ir-8_obj.a.6","label":"IR-08a.06","text":"an incident response plan is developed that provides metrics for measuring the incident response capability within the organization;"},{"id":"ir-8_obj.a.7","label":"IR-08a.07","text":"an incident response plan is developed that defines the resources and management support needed to effectively maintain and mature an incident response capability;"},{"id":"ir-8_obj.a.8","label":"IR-08a.08","text":"an incident response plan is developed that addresses the sharing of incident information;"},{"id":"ir-8_obj.a.9","label":"IR-08a.09","text":"an incident response plan is developed that is reviewed and approved by {{ insert: param, ir-08_odp.01 }} {{ insert: param, ir-08_odp.02 }};"},{"id":"ir-8_obj.a.10","label":"IR-08a.10","text":"an incident response plan is developed that explicitly designates responsibility for incident response to {{ insert: param, ir-08_odp.03 }}."},{"id":"ir-8_obj.b-1","label":"IR-08b.[01]","text":"copies of the incident response plan are distributed to {{ insert: param, ir-08_odp.04 }};"},{"id":"ir-8_obj.b-2","label":"IR-08b.[02]","text":"copies of the incident response plan are distributed to {{ insert: param, ir-08_odp.05 }};"},{"id":"ir-8_obj.c","label":"IR-08c.","text":"the incident response plan is updated to address system and organizational changes or problems encountered during plan implementation, execution, or testing;"},{"id":"ir-8_obj.d-1","label":"IR-08d.[01]","text":"incident response plan changes are communicated to {{ insert: param, ir-08_odp.06 }};"},{"id":"ir-8_obj.d-2","label":"IR-08d.[02]","text":"incident response plan changes are communicated to {{ insert: param, ir-08_odp.07 }};"},{"id":"ir-8_obj.e-1","label":"IR-08e.[01]","text":"the incident response plan is protected from unauthorized disclosure;"},{"id":"ir-8_obj.e-2","label":"IR-08e.[02]","text":"the incident response plan is protected from unauthorized modification."}],"methods":[{"method":"examine","label":"IR-08-Examine"},{"method":"interview","label":"IR-08-Interview"},{"method":"test","label":"IR-08-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-61"},{"title":"OMB M-17-12"}],"related_controls":["AC-2","CP-2","CP-4","IR-4","IR-7","IR-9","PE-6","PL-2","SA-15","SI-12","SR-8"],"enhancements":[{"id":"IR-8(1)","oscal_id":"ir-8.1","family":"IR","title":"Breaches","statement":"Include the following in the Incident Response Plan for breaches involving personally identifiable information:\n(a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed;\n(b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and\n(c) Identification of applicable privacy requirements.","supplemental_guidance":"Organizations may be required by law, regulation, or policy to follow specific procedures relating to breaches, including notice to individuals, affected organizations, and oversight bodies; standards of harm; and mitigation or other specific requirements.","implementation_level":"organization","objectives":[{"id":"ir-8.1_obj.a","label":"IR-08(01)(a)","text":"the incident response plan for breaches involving personally identifiable information includes a process to determine if notice to individuals or other organizations, including oversight organizations, is needed;"},{"id":"ir-8.1_obj.b","label":"IR-08(01)(b)","text":"the incident response plan for breaches involving personally identifiable information includes an assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms;"},{"id":"ir-8.1_obj.c","label":"IR-08(01)(c)","text":"the incident response plan for breaches involving personally identifiable information includes the identification of applicable privacy requirements."}],"methods":[{"method":"examine","label":"IR-08(01)-Examine"},{"method":"interview","label":"IR-08(01)-Interview"},{"method":"test","label":"IR-08(01)-Test"}],"related_controls":["PT-1","PT-2","PT-3","PT-4","PT-5","PT-7"],"is_enhancement":true,"parent_id":"IR-8"}]},{"id":"IR-9","oscal_id":"ir-9","family":"IR","title":"Information Spillage Response","statement":"Respond to information spills by:\na. Assigning <personnel or roles> with responsibility for responding to information spills;\nb. Identifying the specific information involved in the system contamination;\nc. Alerting <personnel or roles> of the information spill using a method of communication not associated with the spill;\nd. Isolating the contaminated system or system component;\ne. Eradicating the information from the contaminated system or component;\nf. Identifying other systems or system components that may have been subsequently contaminated; and\ng. Performing the following additional actions: <actions>.","supplemental_guidance":"Information spillage refers to instances where information is placed on systems that are not authorized to process such information. Information spills occur when information that is thought to be a certain classification or impact level is transmitted to a system and subsequently is determined to be of a higher classification or impact level. At that point, corrective action is required. The nature of the response is based on the classification or impact level of the spilled information, the security capabilities of the system, the specific nature of the contaminated storage media, and the access authorizations of individuals with authorized access to the contaminated system. The methods used to communicate information about the spill after the fact do not involve methods directly associated with the actual spill to minimize the risk of further spreading the contamination before such contamination is isolated and eradicated.","implementation_level":"organization","parameters":[{"id":"ir-09_odp.01","label":"personnel or roles"},{"id":"ir-09_odp.02","label":"personnel or roles"},{"id":"ir-09_odp.03","label":"actions"}],"objectives":[{"id":"ir-9_obj.a","label":"IR-09a.","text":"{{ insert: param, ir-09_odp.01 }} is/are assigned the responsibility to respond to information spills;"},{"id":"ir-9_obj.b","label":"IR-09b.","text":"the specific information involved in the system contamination is identified in response to information spills;"},{"id":"ir-9_obj.c","label":"IR-09c.","text":"{{ insert: param, ir-09_odp.02 }} is/are alerted of the information spill using a method of communication not associated with the spill;"},{"id":"ir-9_obj.d","label":"IR-09d.","text":"the contaminated system or system component is isolated in response to information spills;"},{"id":"ir-9_obj.e","label":"IR-09e.","text":"the information is eradicated from the contaminated system or component in response to information spills;"},{"id":"ir-9_obj.f","label":"IR-09f.","text":"other systems or system components that may have been subsequently contaminated are identified in response to information spills;"},{"id":"ir-9_obj.g","label":"IR-09g.","text":"{{ insert: param, ir-09_odp.03 }} are performed in response to information spills."}],"methods":[{"method":"examine","label":"IR-09-Examine"},{"method":"interview","label":"IR-09-Interview"},{"method":"test","label":"IR-09-Test"}],"related_controls":["CP-2","IR-6","PM-26","PM-27","PT-2","PT-3","PT-7","RA-7"],"enhancements":[{"id":"IR-9(1)","oscal_id":"ir-9.1","family":"IR","title":"Responsible Personnel","statement":"","is_enhancement":true,"parent_id":"IR-9"},{"id":"IR-9(2)","oscal_id":"ir-9.2","family":"IR","title":"Training","statement":"Provide information spillage response training <frequency>.","supplemental_guidance":"Organizations establish requirements for responding to information spillage incidents in incident response plans. Incident response training on a regular basis helps to ensure that organizational personnel understand their individual responsibilities and what specific actions to take when spillage incidents occur.","implementation_level":"organization","parameters":[{"id":"ir-09.02_odp","label":"frequency"}],"methods":[{"method":"examine","label":"IR-09(02)-Examine"},{"method":"interview","label":"IR-09(02)-Interview"}],"related_controls":["AT-2","AT-3","CP-3","IR-2"],"is_enhancement":true,"parent_id":"IR-9"},{"id":"IR-9(3)","oscal_id":"ir-9.3","family":"IR","title":"Post-spill Operations","statement":"Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: <procedures>.","supplemental_guidance":"Corrective actions for systems contaminated due to information spillages may be time-consuming. Personnel may not have access to the contaminated systems while corrective actions are being taken, which may potentially affect their ability to conduct organizational business.","implementation_level":"organization","parameters":[{"id":"ir-09.03_odp","label":"procedures"}],"methods":[{"method":"examine","label":"IR-09(03)-Examine"},{"method":"interview","label":"IR-09(03)-Interview"},{"method":"test","label":"IR-09(03)-Test"}],"is_enhancement":true,"parent_id":"IR-9"},{"id":"IR-9(4)","oscal_id":"ir-9.4","family":"IR","title":"Exposure to Unauthorized Personnel","statement":"Employ the following controls for personnel exposed to information not within assigned access authorizations: <controls>.","supplemental_guidance":"Controls include ensuring that personnel who are exposed to spilled information are made aware of the laws, executive orders, directives, regulations, policies, standards, and guidelines regarding the information and the restrictions imposed based on exposure to such information.","implementation_level":"organization","parameters":[{"id":"ir-09.04_odp","label":"controls"}],"methods":[{"method":"examine","label":"IR-09(04)-Examine"},{"method":"interview","label":"IR-09(04)-Interview"},{"method":"test","label":"IR-09(04)-Test"}],"is_enhancement":true,"parent_id":"IR-9"}]},{"id":"IR-10","oscal_id":"ir-10","family":"IR","title":"Integrated Information Security Analysis Team","statement":""}]};
